import React, { useState, useEffect, useRef } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import * as THREE from 'three';

const ModelLoader = ({ modelPath }) => {
  const [model, setModel] = useState(null);
  const groupRef = useRef(null);
  const { camera } = useThree();

  useEffect(() => {
    const loader = new OBJLoader();
    loader.load(
      modelPath,
      (obj) => {
        // Calculate the bounding box to understand model size
        const box = new THREE.Box3().setFromObject(obj);
        const size = box.getSize(new THREE.Vector3());
        const maxDimension = Math.max(size.x, size.y, size.z);

        // Scale the model proportionally
        const scaleFactor = 2.5 / maxDimension;
        obj.scale.set(scaleFactor, scaleFactor, scaleFactor);

        // Center the model
        box.setFromObject(obj);
        const center = box.getCenter(new THREE.Vector3());
        obj.position.sub(center);

        // Custom edge rendering
        obj.traverse((child) => {
          if (child.isMesh) {
            // Create a custom geometry with only visible edges
            const geometry = child.geometry;
            const positions = geometry.attributes.position.array;
            const normals = geometry.attributes.normal.array;

            const visibleEdges = [];
            const indices = geometry.index ? geometry.index.array : null;

            const addEdge = (a, b) => {
              visibleEdges.push(
                positions[a * 3], positions[a * 3 + 1], positions[a * 3 + 2],
                positions[b * 3], positions[b * 3 + 1], positions[b * 3 + 2]
              );
            };

            // Determine edges based on triangle connectivity
            const processTriangles = indices ? 
              (i) => {
                const a = indices[i];
                const b = indices[i + 1];
                const c = indices[i + 2];

                // Check if triangle is facing camera
                const normalX = normals[a * 3] + normals[b * 3] + normals[c * 3];
                const normalY = normals[a * 3 + 1] + normals[b * 3 + 1] + normals[c * 3 + 1];
                const normalZ = normals[a * 3 + 2] + normals[b * 3 + 2] + normals[c * 3 + 2];

                const normal = new THREE.Vector3(normalX, normalY, normalZ).normalize();
                const viewDirection = new THREE.Vector3(0, 0, 1); // Simplified view direction

                if (normal.dot(viewDirection) > 0) {
                  addEdge(a, b);
                  addEdge(b, c);
                  addEdge(c, a);
                }
              } :
              (i) => {
                const a = i;
                const b = i + 1;
                const c = i + 2;

                // Similar check for non-indexed geometry
                const normalX = normals[a * 3] + normals[b * 3] + normals[c * 3];
                const normalY = normals[a * 3 + 1] + normals[b * 3 + 1] + normals[c * 3 + 1];
                const normalZ = normals[a * 3 + 2] + normals[b * 3 + 2] + normals[c * 3 + 2];

                const normal = new THREE.Vector3(normalX, normalY, normalZ).normalize();
                const viewDirection = new THREE.Vector3(0, 0, 1);

                if (normal.dot(viewDirection) > 0) {
                  addEdge(a, b);
                  addEdge(b, c);
                  addEdge(c, a);
                }
              };

            // Process triangles
            const triangleCount = indices ? indices.length / 3 : geometry.attributes.position.count / 3;
            for (let i = 0; i < triangleCount; i++) {
              processTriangles(i * 3);
            }

            // Create lines geometry from visible edges
            const linesGeometry = new THREE.BufferGeometry();
            linesGeometry.setAttribute('position', new THREE.Float32BufferAttribute(visibleEdges, 3));

            const lineMaterial = new THREE.LineBasicMaterial({ 
              color: 0xffffff, 
              opacity: 0.8,
              transparent: true
            });

            const edgeLines = new THREE.LineSegments(linesGeometry, lineMaterial);

            // Copy transformations from the original mesh
            edgeLines.position.copy(child.position);
            edgeLines.rotation.copy(child.rotation);
            edgeLines.scale.copy(child.scale);

            // Replace the original mesh with edge lines
            child.parent.add(edgeLines);
            child.parent.remove(child);
          }
        });

        // If groupRef exists, add the model to it
        if (groupRef.current) {
          groupRef.current.add(obj);
        }
        setModel(obj);
      },
      undefined,
      (error) => {
        console.error('Error loading OBJ:', error);
      }
    );
  }, [modelPath]);

  // Rotate around the center
  useFrame(() => {
    if (groupRef.current) {
      groupRef.current.rotation.y += 0.003;
    }
  });

  return (
    <group ref={groupRef}>
      {!model && (
        <mesh>
          <boxGeometry args={[1, 1, 1]} />
          <meshBasicMaterial color="white" wireframe={true} />
        </mesh>
      )}
    </group>
  );
};

const App = () => {
  const modelPath = require('./stls/model.obj');

  return (
    <div style={{ height: '100vh', margin: 0 }}>
      <h1 style={{ position: 'absolute', color: 'white', top: '10px', left: '10px', zIndex: 10 }}>
        3D Model Viewer
      </h1>
      <Canvas
        style={{ backgroundColor: 'black' }}
        camera={{ 
          position: [2.5, 2.5, 2.5],
          fov: 45,
        }}
      >
        {/* Lights */}
        <ambientLight intensity={0.5} />
        <spotLight position={[10, 10, 10]} intensity={1} />
        <directionalLight position={[5, 5, 5]} intensity={1} />

        {/* Model loader */}
        <ModelLoader modelPath={modelPath} />

        {/* Orbit controls with limited rotation and no zoom */}
        <OrbitControls 
          enableZoom={false}
          minPolarAngle={Math.PI / 4}
          maxPolarAngle={Math.PI / 4}
          minAzimuthAngle={-Math.PI / 4}
          maxAzimuthAngle={Math.PI / 4}
        />
      </Canvas>
    </div>
  );
};

export default App;
